public class Element_hasClass_TriageGen0Test {

    private Element element;

    @Before
    public void setUp() {
        Attributes attributes = new Attributes();
        attributes.put("class", "");
        element = new Element(Tag.valueOf("div"), "", attributes);
    }

    @Test
    public void testHasClass_withEmptyClassAttribute_returnsFalse() {
        assertFalse(element.hasClass("test"));
    }

    @Test
    public void testHasClass_withNoClassAttribute_returnsFalse() {
        Attributes attributes = new Attributes();
        element = new Element(Tag.valueOf("div"), "", attributes);
        assertFalse(element.hasClass("test"));
    }

    @Test
    public void testHasClass_withExactMatch_returnsTrue() {
        Attributes attributes = new Attributes();
        attributes.put("class", "test");
        element = new Element(Tag.valueOf("div"), "", attributes);
        assertTrue(element.hasClass("test"));
    }

    @Test
    public void testHasClass_withExactMatchCaseInsensitive_returnsTrue() {
        Attributes attributes = new Attributes();
        attributes.put("class", "Test");
        element = new Element(Tag.valueOf("div"), "", attributes);
        assertTrue(element.hasClass("test"));
    }

    @Test
    public void testHasClass_withShorterClassName_returnsFalse() {
        Attributes attributes = new Attributes();
        attributes.put("class", "testClass");
        element = new Element(Tag.valueOf("div"), "", attributes);
        assertFalse(element.hasClass("test"));
    }

    @Test
    public void testHasClass_withLongerClassName_returnsFalse() {
        Attributes attributes = new Attributes();
        attributes.put("class", "testClassName");
        element = new Element(Tag.valueOf("div"), "", attributes);
        assertFalse(element.hasClass("test"));
    }

    @Test
    public void testHasClass_withWhitespaceSurrounded_returnsTrue() {
        Attributes attributes = new Attributes();
        attributes.put("class", " test ");
        element = new Element(Tag.valueOf("div"), "", attributes);
        assertTrue(element.hasClass("test"));
    }

    @Test
    public void testHasClass_withLeadingWhitespace_returnsTrue() {
        Attributes attributes = new Attributes();
        attributes.put("class", " testClass");
        element = new Element(Tag.valueOf("div"), "", attributes);
        assertTrue(element.hasClass("test"));
    }

    @Test
    public void testHasClass_withTrailingWhitespace_returnsTrue() {
        Attributes attributes = new Attributes();
        attributes.put("class", "testClass ");
        element = new Element(Tag.valueOf("div"), "", attributes);
    }

    @Test
    public void testHasClass_withMultipleClasses_returnsTrue() {
        Attributes attributes = new Attributes();
        attributes.put("class", "test class2");
        element = new Element(Tag.valueOf("div"), "", attributes);
        assertTrue(element.hasClass("test"));
    }

    @Test
    public void testHasClass_withMultipleClassesDifferentOrder_returnsTrue() {
        Attributes attributes = new Attributes();
        attributes.put("class", "class2 test");
        element = new Element(Tag.valueOf("div"), "", attributes);
        assertTrue(element.hasClass("test"));
    }

    @Test
    public void testHasClass_withMultipleClassesWithWhitespace_returnsTrue() {
        Attributes attributes = new Attributes();
        attributes.put("class", "test   class2");
        element = new Element(Tag.valueOf("div"), "", attributes);
        assertTrue(element.hasClass("test"));
    }

    @Test
    public void testHasClass_withMultipleClassesAndPunctuation_returnsTrue() {
        Attributes attributes = new Attributes();
        attributes.put("class", "test,class2");
        element = new Element(Tag.valueOf("div"), "", attributes);
        assertTrue(element.hasClass("test"));
    }
}
